--
-- Data for Name: faq; Type: TABLE DATA; Schema: public; Owner: postgres
--

INSERT INTO public.faq (faq_id, faq_category_id, question, answer) VALUES
	(1, 3, 'Nihil bonus est absum demonstro condico.?', 'Reprehenderit creator absens casus recusandae aequus amita sit. Comminor depraedor vinculum vinculum cohors tollo paens voluptates demulceo. Tenuis derideo theatrum cavus annus currus villa desino rem.'),
	(2, 1, 'Apparatus cribro suffragium voluptas aspicio cunctatio alius.?', 'Cotidie hic callide calcar. Vivo commodo sto causa vestrum speculum thorax admiratio patrocinor. Clarus celebrer nisi suffoco ademptio minima assumenda.'),
	(3, 4, 'Qui colo decet contigo.?', 'Delinquo vix conservo taedium causa dolor ipsum compono. Cibo abscido bibo subseco tepidus cibus. Adfero capillus tergum pecto basium causa.'),
	(4, 1, 'Bellicus concido sonitus laudantium degusto velum bonus talio articulus.?', 'Usus defungo surculus tracto appositus suffoco verto. Audax antepono caveo amet dolores aegrus caecus. Demitto maiores sufficio adiuvo aggero adulescens.'),
	(5, 4, 'Adhuc tamen cado vigor depereo decumbo.?', 'Summisse pectus videlicet curis titulus crastinus tum caveo civitas. Benevolentia calco cogo spoliatio valetudo sperno tres illum. Amaritudo iste complectus.'),
	(6, 5, 'Deleniti sophismata creo thorax.?', 'Tabesco voro claustrum similique umbra nihil testimonium cuppedia. Adsidue voro thesaurus ustilo suasoria audax adaugeo. Crustulum celer libero curiositas solio denuo subiungo ultio autus.'),
	(7, 4, 'Debilito vivo copia creator solitudo.?', 'Virgo varius dolores similique adsuesco subito. Contego bonus veritas curso solium ademptio cupio totidem. Pax bellum cur vestigium maxime veniam.'),
	(8, 2, 'Vinco vehemens abduco victus apto adflicto adsidue conscendo quas cuius.?', 'Demoror decimus templum. Blandior cattus cognomen patruus demens. Corrumpo correptius voluptas candidus toties.'),
	(9, 1, 'Abscido vulgo temperantia statim cultellus itaque catena adeptio.?', 'Vel ascisco tersus talio atrox curis curo temporibus tui. Magnam temptatio terror. Esse umquam comis currus.'),
	(10, 1, 'Alii unde colo ab canis alii aliquam suadeo benigne.?', 'Ducimus degero damno stultus defero aperiam utrum cursus aer eveniet. Cetera thesaurus spargo sol curiositas vito certus nesciunt. Tamdiu adiuvo adipisci tondeo damno.'),
	(11, 2, 'Pectus subvenio baiulus audax vitae.?', 'Cribro thesis esse carbo beatae crux undique. Blanditiis varietas animus. Benigne pecto crebro ambitus non statua sponte repellendus.'),
	(12, 2, 'Earum repellat strues sollers ocer armarium bene.?', 'Verto tempore ipsum caste amor. Vapulus amor thema dedecor commodo tactus porro termes aestas comis. Comprehendo desipio cimentarius decor corona.'),
	(13, 3, 'Pax solitudo bene comparo acer amitto celo aedificium.?', 'Vulticulus amaritudo trado angustus spargo sed veniam. Comedo alioqui cum. Terminatio supra expedita vacuus deduco architecto tui cibus adnuo antea.'),
	(14, 2, 'Pectus caveo suscipio terebro verumtamen numquam tergum.?', 'Causa collum demum accusantium coadunatio demitto amita antepono delectatio. Triumphus in demo credo aurum arca textor delego. Succurro aut dolore decor curriculum illo vomito torqueo venio.'),
	(15, 2, 'Aqua ago celebrer.?', 'Sapiente desino venio vigor ascit ultio. Defessus territo aliquid vaco speciosus utique. Eaque aliquid aspernatur commodo amet tot clibanus voluptates subvenio atavus.'),
	(16, 4, 'Deleo depromo facilis addo stipes depono.?', 'Tot callide administratio succedo voluptatum dedecor caveo aro civis. Curriculum sollers certe admitto corroboro. Deripio vobis desparatus cetera aut suasoria facilis peccatus temeritas.'),
	(17, 1, 'Adimpleo thorax expedita cruciamentum fuga perspiciatis architecto cur.?', 'Consequatur aliqua artificiose arx corroboro. Basium cupressus color tersus admitto auxilium bene vulgivagus molestias aptus. Aspicio ante thema derelinquo quos.'),
	(18, 5, 'Iste causa cohors solio arcus.?', 'Ulterius animi velit ager conscendo pel laboriosam. Thermae voluptate attonbitus. Iusto videlicet atque textor adulatio vacuus sperno corpus aufero totam.'),
	(19, 1, 'Contra decor trepide confido alii vere crepusculum.?', 'Bardus velit blandior repellendus utrum. Tribuo cunctatio solus. Sub caterva acer vinitor acceptus.'),
	(20, 4, 'Asporto cruciamentum traho basium uredo deripio copiose somniculosus congregatio.?', 'Tabella collum averto timor tibi. Et subito dolor cur vulgus arceo. Vae stips uxor condico cernuus ullus cruentus.'),
	(21, 4, 'Arceo temperantia inflammatio censura deputo subiungo absum repellendus.?', 'Bos tardus cognomen charisma deludo spes vestrum. Crux aeger tempora dedico. Comminor tutamen facere villa aeternus doloribus tener pauci.'),
	(22, 4, 'Voluptas coadunatio carus.?', 'Id tener crudelis decerno facere cruentus. Ullus deficio a venia ante caries argumentum attero thymbra nihil. Campana depereo voluptatum trepide suscipit audio tenus conqueror excepturi peior.'),
	(23, 2, 'Sursum somniculosus aegrotatio defluo sonitus clementia coma.?', 'Curatio vos circumvenio. Talus abutor velut crepusculum ustulo adficio arbustum. Coniuratio uberrime absum saepe apostolus.'),
	(24, 3, 'Tergo desidero benevolentia reiciendis aro auditor quis vulgaris vallum.?', 'Fugiat vulticulus incidunt curia verbera canis alter. Allatus corroboro curriculum incidunt vulgaris bos coruscus apparatus. Suscipio dens cariosus quas fugit astrum cultura.'),
	(25, 3, 'Vomito ulciscor tabernus valeo tabesco venio.?', 'Defleo tametsi nostrum. Confugo cometes cedo conicio. Umbra talis truculenter vacuus cupressus coniuratio adsuesco.'),
	(26, 4, 'Aedificium talio crapula vinum curia totam cimentarius coaegresco pariatur vulpes.?', 'Video terror theca debeo crepusculum aureus vix. Tametsi clementia caries voveo aeger turpis constans curatio tristis alioqui. Viridis subnecto temeritas templum adulescens.'),
	(27, 3, 'Deprecator corona cunctatio terminatio.?', 'Solutio a advenio. Turba arbor itaque spiritus calculus doloremque. Doloremque ars quisquam omnis acquiro alioqui aro approbo caveo defetiscor.'),
	(28, 4, 'Validus perspiciatis utor et alii.?', 'Traho aut aliqua comprehendo creta cohaero. Casso statim creptio ratione. Inflammatio carpo enim acervus custodia nam attonbitus.'),
	(29, 2, 'Bonus aeneus conqueror volutabrum considero.?', 'Solitudo socius vir umquam thalassinus virgo. Provident valens quia voluptatum. Decens voluptatum crastinus.'),
	(30, 2, 'Adaugeo sub victus crebro acer acsi vapulus suppono.?', 'Adopto tibi tollo. Cogito termes esse. Denique spiculum dolore villa cubitum calculus compello ulterius deripio considero.');


