INSERT INTO public.review (review_id, customer_id, game_id, title, body, posted_at) VALUES
	(1, 161, 54, 'victoria temeritas testimonium amicitia', 'Cumque celebrer nemo traho tergo validus vestrum capio curriculum. Utroque arma universe. Corona adflicto compello valeo acies.', '2025-07-20'),
	(2, 93, 75, 'cultura addo correptius at', 'Utpote debeo certus odit ara. In capio spoliatio deprecator ter. Ancilla conculco comitatus argentum tollo temporibus denuo fugiat adulatio itaque.', '2025-04-15'),
	(3, 74, 69, 'textilis natus cena sopor', 'Impedit depopulo creator super vacuus. Victoria doloremque substantia. Deleo truculenter atrocitas artificiose solum usus vapulus sequi esse.', '2023-09-09'),
	(4, 170, 79, 'conatus vomer comitatus tam', 'Pecus cruentus vobis mollitia viduo absens nam. Tamdiu ventosus abeo a demens adamo voluptatem brevis. Aduro enim crastinus adinventitias conculco cruciamentum.', '2025-01-15'),
	(5, 93, 2, 'vox beatus impedit votum', 'Vulgo volo depraedor subito amor decet tolero despecto subvenio. Catena utique degero bellum uredo cura tandem infit. Tollo nulla crinis amo vehemens adeptio.', '2025-03-15'),
	(6, 111, 79, 'urbanus contigo repudiandae vesco', 'Minima tendo templum est. Templum turba tempus considero vulnus dapifer acidus. Antiquus animus cilicium adnuo sto.', '2023-06-11'),
	(7, 35, 4, 'aer barba aliquam adversus', 'Mollitia vobis utique utor atque. Aestus tergo aegrus iusto carmen. Vulariter templum tui mollitia.', '2024-07-09'),
	(8, 20, 1, 'ut similique vindico cilicium', 'Strues crudelis utroque volva depulso crinis demens. Similique adinventitias id accommodo tergo complectus demens theologus adipiscor. Cubicularis calculus confero vulticulus.', '2023-08-18'),
	(9, 131, 40, 'tremo vado viduo confugo', 'Canis triduana spoliatio canto cotidie. Eum valeo creator ver decet tamen via. Adstringo basium demoror custodia saepe vinco amplexus defero aurum varius.', '2024-07-26'),
	(10, 130, 35, 'vobis demum amet territo', 'Conspergo valens voluptates labore maxime coadunatio nulla decerno. Aegre casus avaritia id pauper. Cresco curiositas trucido demonstro votum decerno sodalitas.', '2025-02-22'),
	(11, 179, 58, 'admitto solitudo ullus vilitas', 'Cilicium necessitatibus defendo magni ars umerus verbera defaeco cicuta aqua. Color verbera speciosus sint laboriosam adipisci vicinus quisquam. Fuga sulum adstringo ratione tendo tergo tepesco calamitas voluptates vulnero.', '2026-05-24'),
	(12, 149, 10, 'aestivus video clam strenuus', 'Volaticus ambitus deripio cursus comparo. Aperte sumptus vomer thymum undique contigo communis ea. Vinculum arbitro venio.', '2025-11-01'),
	(13, 151, 21, 'agnosco traho argentum adficio', 'Cibus summopere itaque amitto vicissitudo defero tabernus desino. Cognatus averto illo decerno cribro spectaculum strues. Confido cupiditas alo.', '2025-04-13'),
	(14, 149, 37, 'canto admoneo vulnus tabgo', 'Accusator super decens. Vesica patruus audentia tero vis nisi statim confero creber. Vestigium quo texo astrum beneficium exercitationem atqui rem.', '2024-10-17'),
	(15, 20, 71, 'claro textilis titulus delectus', 'Sit vulgivagus quasi adeptio. Commemoro autus torqueo. Caute comparo capillus ver desolo sollicito cupressus quos creptio.', '2024-12-30'),
	(16, 35, 78, 'conforto reiciendis officiis claudeo', 'Corporis cuppedia quo vergo. Careo aut desipio. Suspendo carcer paens vacuus verbum vitae.', '2023-09-20'),
	(17, 8, 8, 'terebro ventus canonicus avaritia', 'Suffragium viduo audentia. Tamen vestigium sit voluntarius conitor consectetur illo credo. Synagoga tantillus tametsi.', '2025-07-03'),
	(18, 193, 29, 'conitor enim contigo acceptus', 'Anser ager temeritas absque vitiosus dolorum vorago. Nostrum conscendo turpis. Cavus umquam corrupti acceptus cribro.', '2024-05-15'),
	(19, 27, 4, 'solium caterva custodia adstringo', 'Temperantia cupiditate curia alienus baiulus arma dens. Vinum aer pauci est ducimus uterque basium. Spectaculum conitor accommodo.', '2023-11-23'),
	(20, 63, 28, 'caste collum provident at', 'Dens degenero voluptate adipisci virgo non. Curtus defetiscor utroque vel capitulus aveho derelinquo velut commodi. Suggero tergo magni culpa volaticus perferendis suscipit conitor.', '2023-03-30'),
	(21, 182, 3, 'spargo causa caries sumo', 'Statua centum patruus decor patria clamo sumo. Caveo coerceo solvo sub succurro statua crudelis crur caterva. Stultus aliquid viduo trepide.', '2024-05-25'),
	(22, 163, 11, 'umquam ventus cunabula tyrannus', 'Acer territo aestas voveo. Tardus cariosus sperno adimpleo tui assentator subiungo caelestis. Dens assentator suspendo.', '2025-09-14'),
	(23, 65, 47, 'capio conicio minima cinis', 'Tot attero agnitio compono curriculum illo. Texo adflicto custodia creber sit. Dolore vos cogito adaugeo asperiores crur comes alo damnatio confero.', '2026-03-18'),
	(24, 191, 63, 'annus clementia valde cogito', 'Perspiciatis curso capitulus corporis omnis consequatur bestia angelus. Decerno quibusdam depraedor uter incidunt denique vesper super amoveo atrocitas. Tubineus impedit iste ratione decens sponte amitto vito tandem.', '2025-11-20'),
	(25, 193, 25, 'quos comes arto cunabula', 'Reiciendis crebro placeat torqueo acquiro defendo tempora in. Ea vulgaris adopto deprecator aliqua artificiose crebro armarium. Vindico condico rerum explicabo tot quis a tenax tametsi dolore.', '2026-01-06'),
	(26, 1, 2, 'venio ver error pecus', 'Coaegresco communis auctor vehemens tam amiculum vomica suus ullam administratio. Sublime illo sophismata toties corrumpo ubi ascisco. Adimpleo copia crastinus tibi solitudo.', '2024-03-07'),
	(27, 8, 1, 'debilito solio admoveo attollo', 'Saepe teres culpa suppono stella vix bestia ipsam. Vulticulus averto eos coniuratio est campana adiuvo. Condico attonbitus commodo admiratio virga nobis torrens.', '2024-02-29'),
	(28, 26, 47, 'curo venio denuncio natus', 'Tabella minima cernuus arbustum pecto deporto. Crustulum dolorum tres. Conscendo traho socius.', '2026-04-13'),
	(29, 14, 4, 'clam tutis depromo deripio', 'Vinitor contego aqua comparo adaugeo accusator crustulum vilis ut dolorem. Abscido bibo acidus tego arbustum ustulo sed. Ars quis velut supellex.', '2024-11-09'),
	(30, 109, 49, 'conscendo ocer colo xiphias', 'Porro curo quae congregatio ad crur via quidem. Vae censura careo. Neque impedit deprecator sunt comes.', '2025-08-19'),
	(31, 50, 69, 'tero atque tero sonitus', 'Dens sopor ager ullus adsidue arcesso neque tactus. Verumtamen voluptate pecto. Talio compono depromo veritatis vis vestigium.', '2025-05-20'),
	(32, 86, 49, 'celebrer candidus coadunatio decet', 'Corrumpo quas tempus tabesco torrens. Adiuvo testimonium expedita. Admoveo cattus reprehenderit unde vero desidero impedit.', '2023-03-02'),
	(33, 169, 19, 'triumphus fugiat ea ventosus', 'Verbera blanditiis error turbo amoveo thalassinus auctor titulus perspiciatis. Demergo statim reiciendis curso. Earum dicta advenio vesco atqui eum thymbra bibo et caput.', '2025-06-06'),
	(34, 92, 77, 'tempore magni umerus varius', 'Surgo inflammatio creo socius ver cur comburo creta. Aer deripio depulso odio conventus placeat. Vis nulla adicio volubilis suffoco condico arceo arbitro aspicio adipisci.', '2024-05-29'),
	(35, 194, 41, 'veniam hic subseco tribuo', 'Vaco volaticus decens virga supra aeneus statim stips ventosus. Numquam abundans conatus advenio enim. Beatae et barba animi dolorem ager ocer addo amissio.', '2023-06-21'),
	(36, 111, 79, 'inventore officiis ad nam', 'Suppono apostolus omnis spectaculum adfero umbra ventus ullam tredecim. Recusandae spiritus timidus somniculosus complectus coruscus velit accommodo. Virtus suffoco vulgo stips adeo tres cinis decumbo.', '2023-09-14'),
